 function openReset(){if(!active||!shown||!currentContext(shown)||E.hasPending()||!active||reset.disabled)return;if(typeof resetDialog.showModal!=='function'){setFeedback('当前浏览器不支持安全确认对话框，未执行重置。请使用支持 dialog 的浏览器。');return;}resetContext=Object.freeze({...shown});resetLaunch=reset;resetConfirm.disabled=false;resetDialog.querySelector('[data-reset-stale]').textContent='';resetDialog.showModal();if(active)resetDialog.querySelector('[data-reset-cancel]').focus();}
