function profileNavigate(e){const target=e.target.closest?.('[data-profile-href],.profile-management-entry');if(!target)return;if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;e.preventDefault();if(!active||!shown||!currentContext(shown)||!E.confirmLeave(false)||!active)return;w.location.href=target.dataset.profileHref||target.getAttribute('href');}if(page==='profile'){anchor.addEventListener('click',profileNavigate);anchor.addEventListener('keydown',profileNavigate);}
function setFeedback(text){if(active)feedback.textContent=text;}
function currentContext(expected){if(!active||!expected)return false;try{const actual=S.context();return active&&equal(expected,actual);}catch(e){if(active)invalid(e.message);return false;}}
const fields=['mode','accountId','protocolVersion','epoch','generation','revision'];function context(s){return Object.fromEntries(fields.map(k=>[k,s.meta[k]]));}function equal(a,b){return !!a&&!!b&&fields.every(k=>a[k]===b[k]);}
