function invalid(text){if(!active)return;shown=null;if(page==='profile')anchor.textContent='当前合成记录需要重新核对，请刷新后重新进入；现有记录没有改写。';summary.textContent='当前合成记录需要重新核对，不能据旧画面继续写入。';setFeedback(text);if(storageNote)storageNote.textContent='当前存储方式尚未核对，不能据旧状态确认持久保存。';reread.disabled=initializing;if(reset)reset.disabled=true;if(restore)restore.disabled=true;if(resetConfirm)resetConfirm.disabled=true;}
function render(s){if(!active)return false;try{const c=context(s);if(!currentContext(c)){if(active)invalid('记录已变化，请重新读取；没有把新权限附在旧数据上。');return false;}const state=S.status();if(!active)return false;shown=c;if(page==='profile')renderOriginalProfile(s);summary.textContent=`${s.profile.name} · ${s.health.demoDate} 演示日 · ${s.health.meals.length} 条餐食 / ${s.commerce.orders.length} 个演示订单 / ${s.practitioner.registration?.events?.length||0} 条登记操作记录`;branch.textContent=`当前 v${c.protocolVersion} · 代际 ${c.generation} / 版本 ${c.revision}；来源 ${s.meta.source.key}。${state.persistent?'仅此浏览器的合成分支。':'仅本页内存，导航或刷新即丢失。'}`;controls();return active;}catch(e){invalid(e.message);return false;}}
function refresh(){try{return render(S.read());}catch(e){invalid(e.message);return false;}}
function accountSuccess(r){if(!active)return;try{if(currentContext(context(r.state))){if(!render(r.state)||!active)return;const state=S.status();if(!active)return;setFeedback(state.persistent?'整账号操作已核验保存；旧角色、表单和同意均已失效。':'整账号操作已完成，仅本页内存保留。');}else{if(!active)return;refresh();setFeedback('整账号操作已写入，随后数据又有更新，请核对当前记录。');}}catch(e){invalid(e.message);}}
function accountError(e){if(!active)return;setFeedback(e.outcome==='unknown'?'操作结果尚未核对。请使用上方原请求重试，勿再次发起新重置。':e.outcome==='committed'?'写入已核验，当前界面需要重新读取。':e.message);controls();}
function destroy(){if(!active)return;if(page==='profile'){anchor.removeEventListener('click',profileNavigate);anchor.removeEventListener('keydown',profileNavigate);}active=false;initSerial++;shown=null;resetContext=null;if(resetDialog?.open)resetDialog.close();reread.disabled=true;if(reset)reset.disabled=true;if(restore)restore.disabled=true;unsubscribe?.();unentry?.();if(page==='profile')anchor.textContent='当前账号页面已停用，请重新打开完整版本核对。';section.replaceChildren();section.append(node('p','当前账号页面已停用，请重新打开完整版本核对。'));w.removeEventListener('pagehide',destroy);}
w.addEventListener('pagehide',destroy);unentry=E.subscribe(controls);
async function initialize(){if(!active||initializing||E.hasPending())return false;const ticket=++initSerial,guard=()=>active&&ticket===initSerial;initializing=true;shown=null;controls();try{await S.initialize({guard});if(!guard())return false;if(!unsubscribe)unsubscribe=S.subscribe((next)=>{if(!active||initializing)return;if(next)render(next);else invalid('存档暂不可读，保留原数据，请点击重新读取当前合成记录。');});const ok=refresh();if(ok&&guard()){const state=S.status();if(!guard())return false;setFeedback(state.notice);if(page==='settings'&&!initialHashHandled){initialHashHandled=true;if(w.location.hash==='#reset')queueMicrotask(()=>{if(active&&!initializing)reset.click();});}}return ok;}catch(e){if(guard())invalid(e.message+'；请点击重新读取当前合成记录。没有自动清空或重建。');return false;}finally{if(guard()){initializing=false;controls();}}}
